INSERT OR REPLACE INTO events (id,kind,name_en,name_hi,date_from,date_to,places,visit_factor,travel_factor,blurb_en,blurb_hi,notice_en,notice_hi,bias,img,win_from,win_to,corridor,advice,updated_at) VALUES ('janmashtami-2026','festival','Shri Krishna Janmashtami','श्री कृष्ण जन्माष्टमी','2026-09-04','2026-09-05','["iskcon","gaudiya-math","birla-mandir","jyotisar","krishna-museum"]',1.5,1.25,'Midnight aarti, jhankis and kirtan at every Krishna temple in the district.','जिले के हर कृष्ण मंदिर में मध्यरात्रि आरती, झांकियाँ और कीर्तन।','Temples stay open late and fill up after dark — come in the morning if you want a quiet darshan.','मंदिर देर रात तक खुले रहते हैं और अँधेरे के बाद भर जाते हैं — शांत दर्शन के लिए सुबह आएँ।','{"jyotisar":50,"iskcon":40}',NULL,NULL,NULL,NULL,NULL,1785754690314);
INSERT OR REPLACE INTO events (id,kind,name_en,name_hi,date_from,date_to,places,visit_factor,travel_factor,blurb_en,blurb_hi,notice_en,notice_hi,bias,img,win_from,win_to,corridor,advice,updated_at) VALUES ('somvati-amavasya-2026-10','snan','Somvati Amavasya snan','सोमवती अमावस्या स्नान','2026-10-19','2026-10-19','["brahma-sarovar","sannihit-sarovar","sthaneshwar","bhishma-kund"]',1.6,1.35,'A new moon falling on a Monday — the day pilgrims bathe at Sannihit and Brahma Sarovar.','सोमवार को पड़ने वाली अमावस्या — इस दिन तीर्थयात्री सन्निहित और ब्रह्म सरोवर में स्नान करते हैं।','The ghats are busiest between dawn and noon. Parking near the sarovars is closed to cars.','घाट भोर से दोपहर तक सबसे व्यस्त रहते हैं। सरोवरों के पास कारों की पार्किंग बंद रहती है।','{"sannihit-sarovar":55,"brahma-sarovar":45}',NULL,NULL,NULL,NULL,NULL,1785754690314);
INSERT OR REPLACE INTO events (id,kind,name_en,name_hi,date_from,date_to,places,visit_factor,travel_factor,blurb_en,blurb_hi,notice_en,notice_hi,bias,img,win_from,win_to,corridor,advice,updated_at) VALUES ('gita-mahotsav-2026','mela','International Gita Mahotsav','अंतर्राष्ट्रीय गीता महोत्सव','2026-12-10','2026-12-20','["brahma-sarovar","sannihit-sarovar","jyotisar","krishna-museum","dharohar"]',1.8,1.4,'Eleven days of aarti, shobha yatra and shilp mela on the Brahma Sarovar ghats.','ब्रह्म सरोवर के घाटों पर ग्यारह दिन की आरती, शोभायात्रा और शिल्प मेला।','Expect heavy crowds and road diversions around Brahma Sarovar. Allow far longer than usual for every stop in the centre.','ब्रह्म सरोवर के आसपास भारी भीड़ और मार्ग परिवर्तन की संभावना। केंद्र के हर पड़ाव के लिए सामान्य से बहुत अधिक समय रखें।','{"brahma-sarovar":60,"jyotisar":40}',NULL,NULL,NULL,NULL,NULL,1785754690314);
INSERT OR REPLACE INTO events (id,kind,name_en,name_hi,date_from,date_to,places,visit_factor,travel_factor,blurb_en,blurb_hi,notice_en,notice_hi,bias,img,win_from,win_to,corridor,advice,updated_at) VALUES ('gita-shobha-yatra-2026','yatra','Gita Shobha Yatra','गीता शोभा यात्रा','2026-12-14','2026-12-14','["brahma-sarovar","sthaneshwar","sannihit-sarovar"]',1.4,1.6,'A procession of decorated tableaux from Sthaneshwar to Brahma Sarovar.','स्थाणेश्वर से ब्रह्म सरोवर तक सजी झांकियों की शोभा यात्रा।','The Jhansa road and the sarovar approach close to traffic from about 4pm. Allow an extra half hour, or walk.','झांसा रोड और सरोवर का रास्ता लगभग 4 बजे से बंद रहता है। आधा घंटा अतिरिक्त रखें, या पैदल चलें।','{"brahma-sarovar":40}',NULL,'16:00','18:30','[{"lat":29.9695,"lng":76.8181},{"lat":29.9662,"lng":76.8265},{"lat":29.9633,"lng":76.8342},{"lat":29.9608,"lng":76.8398}]','avoid',1785754690314);
